"""Syntax + structural validation for webhook.py (no Flask/Stripe needed)."""
import ast
import sys

SOURCE = "webhook.py"


def main() -> int:
    with open(SOURCE, encoding="utf-8") as fh:
        source = fh.read()

    tree = ast.parse(source, filename=SOURCE)  # raises SyntaxError if invalid

    funcs = {
        n.name
        for n in ast.walk(tree)
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
    }

    required = {
        "webhook_received",
        "handle_payment_succeeded",
        "handle_payment_failed",
        "_is_event_processed",
        "_mark_event_processed",
    }
    missing = required - funcs
    if missing:
        print(f"FAIL: missing functions: {sorted(missing)}")
        return 1

    routes = []
    for n in ast.walk(tree):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == "route":
            arg = n.args[0]
            if isinstance(arg, ast.Constant):
                routes.append(arg.value)

    if "/webhook" not in routes:
        print("FAIL: no route registered for /webhook")
        return 1

    handled = {c.args[0].value for c in ast.walk(tree)
               if isinstance(c, ast.Compare)
               and any(isinstance(x, ast.Constant) and x.value == "payment_intent.succeeded" for x in c.comparators)}
    if "payment_intent.succeeded" not in str(source) or "payment_intent.payment_failed" not in str(source):
        print("FAIL: event types not referenced")
        return 1

    print("OK: syntax valid, all required handlers present, /webhook route registered")
    return 0


if __name__ == "__main__":
    sys.exit(main())
